# WAR ARENA - .env.example (template only, safe for git) - Installer
# Writes .env.example to the project root. This is the BLANK template.
# Your real .env (with secrets) is created separately and never committed.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-env-example.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - .env.example installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 ".env.example" ""

Write-Host ""; Write-Host ".env.example written." -ForegroundColor Green
Write-Host "Next: copy it to .env and fill in your real values:" -ForegroundColor Yellow
Write-Host "  Copy-Item .env.example .env" -ForegroundColor Gray
Write-Host "Your .env stays local (git ignores it). Never commit real secrets." -ForegroundColor Yellow
